function requestNativeStapleClearStore(){try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'CLEAR_NATIVE_STAPLE_STORE'}));return}}catch(_){ }flash(copy('nativeJourneyUnavailable'))}
function requestNativeStapleClearSelection(){try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'CLEAR_NATIVE_STAPLE_SELECTION'}));return}}catch(_){ }flash(copy('nativeJourneyUnavailable'))}
function requestNativeStapleSubmit(){try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'SUBMIT_NATIVE_STAPLE_WATCH'}));return}}catch(_){ }flash(copy('nativeJourneyUnavailable'))}
function requestNativeStapleCancel(){state.nativeStapleWatchPending=false;state.nativeStapleWatchState=null;try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'CANCEL_NATIVE_STAPLE_WATCH'}));return}}catch(_){ }navigate('saved',{skipHistory:true})}
function receiveNativeStapleWatch(payload){if(!payload||typeof payload!=='object')return;state.nativeStapleWatchPending=false;state.nativeStapleWatchState=payload?.state||null;render()}
function receiveNativeObservedPrice(payload){if(!payload||typeof payload!=='object')return;state.nativeObservedPricePending=false;state.nativeObservedPriceSelection=payload.selection||null;state.nativeObservedPricePrefill=payload.prefill||null;state.nativeObservedPriceConfirmation=payload.confirmation||null;if(payload.phase==='CONFIRMATION'){if(state.page!=='observed-confirm')navigate('observed-confirm',{skipHistory:true})}else if(state.page==='observed-confirm'){navigate('observed-price',{skipHistory:true})}render()}
function observedNativeMessage(message){const raw=String(message||'');if(state.language===LANGUAGES.EN)return raw;if(raw.includes('required fields'))return copy('observedConfirmMissing');if(raw.includes('Checking the confirmation'))return copy('observedConfirmSubmitting');if(raw.includes('Observed price confirmed'))return copy('observedConfirmSuccess');if(raw.includes('could not be completed')||raw.includes('could not be accepted'))return copy('observedConfirmError');if(raw.includes('When the required fields'))return copy('observedConfirmReady');return raw}
function observedNativeError(error){return error?copy('observedConfirmInputError'):''}
function requestNativeTrip(values){state.nativeTripPending=true;state.nativeTripState=null;render();try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'CALCULATE_NATIVE_TRIP',oneWayDistance:String(values.distance),fuelConsumption:String(values.consumption),fuelPrice:String(values.fuel),tolls:String(values.tolls),parking:String(values.parking)}));return}}catch(_){ }state.nativeTripPending=false;state.nativeTripState={status:'ERROR',error:copy('nativeTripError')};render()}
function receiveNativeTrip(payload){if(!payload||typeof payload!=='object')return;state.nativeTripPending=false;state.nativeTripState=payload;render()}
function nativeTripResults(payload){if(state.nativeTripPending)return `<div class="empty-state">${icons('route')}<strong>${copy('nativeTripLoading')}</strong><p>${copy('nativeTripIntro')}</p></div>`;if(!payload)return `<div class="empty-state">${icons('route')}<strong>${copy('nativeTripTitle')}</strong><p>${copy('nativeTripIntro')}</p></div>`;if(payload.status!=='SUCCESS'||!payload.result)return `<div class="empty-state">${icons('info')}<strong>${copy('nativeTripError')}</strong><p>${copy('nativeTripErrorDetail')}</p></div>`;const r=payload.result;return `<div class="summary-total" style="margin-top:14px"><div class="split"><span style="font-size:12px">${copy('nativeTripTotal')}</span><span class="pill" style="background:#ffffff22;color:inherit">ARS</span></div><div class="number-lg" style="margin-top:10px">${nativeCurrency(r.total)}</div><div class="micro" style="color:#dadbd5">${copy('nativeTripRoundTrip')}: ${safe(r.roundTripKm)} km</div><div class="trip-breakdown"><span>${copy('nativeTripFuel')} <strong>${nativeCurrency(r.fuelCost)}</strong></span><span>${copy('nativeTripTolls')} <strong>${nativeCurrency(r.tolls)}</strong></span><span>${copy('nativeTripParking')} <strong>${nativeCurrency(r.parking)}</strong></span></div></div>`}
function persistLanguage(language){try{window.localStorage.setItem(LANGUAGE_KEY,language)}catch(_){ }try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function')window.ValuePilotHost.postMessage(JSON.stringify({type:'SET_LANGUAGE',language:language}))}catch(_){ }}
function setLanguage(next,options={}){const language=next===LANGUAGES.ES_AR?LANGUAGES.ES_AR:LANGUAGES.EN;const scroll=window.scrollY||document.documentElement.scrollTop;if(state.language===language){updateChrome();return}state.language=language;if(options.persist!==false)persistLanguage(language);render();requestAnimationFrame(()=>window.scrollTo({top:scroll,behavior:'auto'}))}
function updateChrome(){document.documentElement.lang=state.language;document.title=copy('pageTitle');document.body.classList.toggle('search-clean',state.page==='search');const description=document.querySelector('meta[name=description]');if(description)description.setAttribute('content',copy('metaDescription'));const set=(id,value)=>{const element=document.getElementById(id);if(element)element.textContent=value};set('brandLocation',nativeAreaLabel());set('navHomeLabel',copy('navHome'));set('navSearchLabel',copy('navSearch'));set('navBasketLabel',copy('navBasket'));set('navSavedLabel',copy('navSaved'));const brand=document.querySelector('#brandButton');if(brand)brand.setAttribute('aria-label',copy('backHome'));const theme=document.querySelector('#themeToggle');if(theme){theme.setAttribute('aria-label',copy('themeAria'));theme.setAttribute('title',copy('themeTitle'))}const settingsButton=document.querySelector('#settingsButton');if(settingsButton)settingsButton.setAttribute('aria-label',copy('preferences'));if(nav)nav.setAttribute('aria-label',copy('navLabel'));document.querySelectorAll('.language-toggle').forEach(group=>group.setAttribute('aria-label',copy('language')));document.querySelectorAll('[data-language]').forEach(button=>{const active=button.dataset.language===state.language;button.setAttribute('aria-pressed',active?'true':'false');button.setAttribute('aria-label',button.dataset.language===LANGUAGES.EN?copy('english'):copy('spanishArgentina'))})}
function render(){if(state.page==='search')saveScroll();main.innerHTML=({home:home,search:search,detail:nativeDetail,basket:basket,saved:saved,trip:trip,settings:settings,'observed-price':observedPrice,'observed-confirm':observedConfirm,'staple-watch':stapleWatch,'private-history':privateHistory})[state.page]();updateChrome();const parentNav=['home','search','basket','saved'].includes(state.from)?state.from:'search';nav.querySelectorAll('button[data-nav]').forEach(btn=>{const active=btn.dataset.nav===state.page||((state.page==='detail'||state.page==='trip')&&btn.dataset.nav===parentNav);btn.classList.toggle('active',active);btn.setAttribute('aria-current',active?'page':'false')});const nativeCount=Number(state.nativeSavedState?.items?.length||0);bubble.hidden=!nativeCount;bubble.textContent=nativeCount;requestAnimationFrame(()=>{const restore=state.restoreSearchViewport;const matrix=document.querySelector('#matrixScroll');if(restore){window.scrollTo({top:restore.searchScroll,behavior:'auto'});state.searchScroll=restore.searchScroll;state.matrixScrollTop=restore.matrixScrollTop;state.matrixScrollLeft=restore.matrixScrollLeft;state.restoreSearchViewport=null}if(matrix){installMatrixPan(matrix);const top=state.matrixScrollTop||0;const left=state.matrixScrollLeft||0;matrix.style.scrollBehavior='auto';matrix.scrollTo({top,left,behavior:'auto'});matrix.style.scrollBehavior=''}});}
function home(){const items=Array.isArray(state.nativeSavedState?.items)?state.nativeSavedState.items:[];const count=items.length;return `<section class="content"><div class="home-intro"><div class="row"><span class="pill orange">● ${copy('unitPrices')}</span><span class="pill">CABA</span></div><h1 class="hero-title">${copy('heroTitle')}</h1><p class="hero-copy">${copy('heroCopy')}</p></div>
  <div class="search-bar home-search">${icons('search')}<input id="homeQuery" aria-label="${safe(copy('searchProduct'))}" placeholder="${safe(copy('searchPlaceholder'))}" value="${safe(state.query)}"><button class="btn btn-primary" data-action="go-search">${copy('search')} ${icons('arrow')}</button></div>
  <div class="home-stat"><div class="card card-dark"><div class="module-title">${copy('nativeBasketTitle')} <span class="pill" style="float:right;background:#ffffff26;color:inherit">${itemCount(count)}</span></div><div><div class="number-lg">${count?itemCount(count):copy('basketTitle')}</div><p class="micro">${copy('nativeEvidence')}</p></div><button class="btn btn-outline" style="font-size:11px" data-nav="basket">${copy('viewBasket')} ${icons('arrow')}</button></div>
  <div class="card"><div class="module-title">${copy('nativeTripTitle')}</div><div class="number-lg" style="font-size:22px;margin-top:12px">${copy('nextTrip')}</div><p class="small">${copy('nativeTripIntro')}</p><button class="btn btn-primary btn-fill" data-nav="trip">${icons('route')} ${copy('planTrip')}</button></div></div>
  <div class="section-header"><strong>${copy('comparison')}</strong><button data-nav="search">${copy('viewAll')} ${icons('arrow')}</button></div><div class="home-cats"><button class="chip active" data-action="category" data-category="Leche">${copy('dairy')}</button><button class="chip" data-action="category" data-category="Arroz">${copy('pantry')}</button><button class="chip" data-action="category" data-category="Aceite">${copy('oils')}</button></div>
  <div class="card stack" style="margin-top:15px">${icons('info')}<strong>${copy('nativeSearchTitle')}</strong><p class="micro">${copy('nativeSearchIntro')}</p><button class="btn btn-soft btn-fill" data-nav="search">${copy('searchProducts')} ${icons('arrow')}</button></div></section>`}
function matrixMoney(value,currencyCode='ARS'){if(value==null||!Number.isFinite(Number(value)))return '—';return `${safe(currencyCode||'ARS')} ${nativeAmount(Number(value))||money(Number(value))}`}
function finiteDistance(value){const distance=Number(value);return Number.isFinite(distance)&&distance>=0?distance:null}
function distanceLabel(value){const distance=finiteDistance(value);if(distance==null)return '';return distance<1?`${Math.round(distance*1000)} m`:`${distance<10?distance.toFixed(1):distance.toFixed(0)} km`}
function matrixRowsForNativeFlat(payload){const generation=payload?.generation||0;return (payload?.matches||[]).flatMap((match,index)=>{const offers=Array.isArray(match.offers)&&match.offers.length?match.offers:[null];const id=nativeProductId(generation,index);return offers.map((offer,offerIndex)=>({id,product:match.displayName||'',brand:match.brand||'',quantity:match.packageQuantityLabel||'',unitValue:offer?.unitPriceAmount!=null?Number(offer.unitPriceAmount):null,unitCurrency:offer?.unitPriceCurrency||offer?.currency||'ARS',unitBasis:offer?.unitPriceBasis||'',packValue:offer?.priceAmount!=null?Number(offer.priceAmount):null,packCurrency:offer?.currency||'ARS',store:offer?.storeName||'',freshness:offer?.freshness||'',distance:offer?.distanceKm!=null?finiteDistance(offer.distanceKm):null,fuel:null,total:null,native:true,match,identityKey:match.identityKey||'',offerKey:offer?.offerKey||'',query:payload?.query||state.query,offerIndex}))})}
function matrixRowsForNative(payload){return matrixRowsForNativeFlat(payload)}
function matrixRowsWithIdentityVisibility(rows){
  const seen=new Set();
  return rows.map(row=>{
    const key=row.identityKey||[row.product,row.brand,row.quantity].join('|');
    const hideIdentity=seen.has(key);
    seen.add(key);
    return {...row,hideIdentity};
  });
}function matrixIdentityCount(rows){return new Set(rows.map(row=>row.identityKey||[row.product,row.brand,row.quantity].join('|'))).size}
function matrixRowMeta(row){return [row.brand,row.quantity].map(value=>String(value||'').trim()).filter(Boolean).join(' · ')}
function matrixRowsSorted(rows){const value=(row,key)=>{const raw=row[key];if(raw==null||String(raw).trim()==='')return null;const n=Number(raw);return Number.isFinite(n)?n:null};return [...rows].sort((a,b)=>{let result=0;switch(state.matrixSort){case'pack':result=(value(a,'packValue')??Infinity)-(value(b,'packValue')??Infinity);break;case'store':result=String(a.store||'').localeCompare(String(b.store||''));break;case'distance':result=(value(a,'distance')??Infinity)-(value(b,'distance')??Infinity);break;case'unit':default:result=(value(a,'unitValue')??Infinity)-(value(b,'unitValue')??Infinity);break}return result||String(a.product||'').localeCompare(String(b.product||''))||String(a.brand||'').localeCompare(String(b.brand||''))||String(a.identityKey||'').localeCompare(String(b.identityKey||''))||String(a.offerKey||'').localeCompare(String(b.offerKey||''))})}
function matrixStoreOptions(rows){const stores=new Map();rows.forEach(row=>{const name=String(row.store||'').trim();if(!name)return;const distance=finiteDistance(row.distance);const current=stores.get(name);if(!current||current.distance==null||(distance!=null&&distance<current.distance))stores.set(name,{name,distance})});return [...stores.values()].sort((a,b)=>(a.distance??Infinity)-(b.distance??Infinity)||a.name.localeCompare(b.name))}
function matrixFilteredRows(rows){const hasStore=state.matrixStore!=='all'&&rows.some(row=>String(row.store||'')===state.matrixStore);const filtered=hasStore?rows.filter(row=>String(row.store||'')===state.matrixStore):rows;return matrixRowsSorted(filtered)}
function matrixSortLabel(){switch(state.matrixSort){case'pack':return copy('matrixSortPack');case'product':return copy('matrixSortProduct');case'store':return copy('matrixSortStore');case'distance':return copy('matrixSortDistance');default:return copy('matrixSortUnit')}}
function matrixRow(row,index){const productAttrs=`data-identity-key="${safe(row.identityKey)}" data-query="${safe(row.query||state.query)}"`;const unit=row.unitValue==null?'—':matrixMoney(row.unitValue,row.unitCurrency);const pack=row.packValue==null?'—':matrixMoney(row.packValue,row.packCurrency);const unitLabel=row.unitValue==null?copy('matrixUnavailable'):row.unitBasis?`ARS / ${safe(row.unitBasis)}`:'ARS / unit';const freshness=row.freshness?nativeFreshnessLabel(row.freshness):copy('matrixUnavailable');const ariaProduct=`${safe(row.product)}${row.brand?` · ${safe(row.brand)}`:''}`;const distance=distanceLabel(row.distance);const rowMeta=matrixRowMeta(row);const actions=`<div class="matrix-product-actions"><button class="matrix-action" data-action="photos" data-id="${safe(row.id)}" aria-label="${safe(copy('matrixGoogleImages'))}: ${ariaProduct}" title="${safe(copy('matrixGoogleImages'))}">${icons('camera')}</button><button class="matrix-action" data-action="native-map" data-identity-key="${safe(row.identityKey||'')}" data-offer-key="${safe(row.offerKey||'')}" data-query="${safe(row.query||state.query)}" aria-label="${safe(copy('matrixOpenMap'))}: ${safe(row.store||'')}" title="${safe(copy('matrixOpenMap'))}">${icons('pin')}</button><button class="matrix-action matrix-add" data-action="native-save" data-id="${safe(row.id)}" aria-label="${safe(copy('matrixAddNative'))}: ${ariaProduct}" title="${safe(copy('matrixAddNative'))}">${icons('plus')}</button></div>`;return `<tr class="matrix-row" data-action="native-detail" ${productAttrs} tabindex="0" aria-label="${ariaProduct}, ${safe(row.quantity||'')}, ${safe(pack)} pack price, ${safe(unit)} per unit, ${safe(row.store||'')}${distance?`, ${distance}`:''}"><td class="matrix-product ${row.hideIdentity?'matrix-product-duplicate':''}"><div class="matrix-name" title="${ariaProduct}">${safe(row.product)}</div><div class="matrix-meta" title="${safe(rowMeta)}">${safe(rowMeta)}</div>${actions}</td><td class="matrix-pack right"><span class="matrix-money">${safe(pack)}</span></td><td class="matrix-unit right"><div class="matrix-unit-value">${safe(unit)}</div><div class="matrix-unit-label">${unitLabel}</div></td><td class="matrix-store"><span title="${safe(row.store||'')}">${safe(row.store||copy('nativeIdentityOnly'))}</span><small>${safe(freshness)}</small></td><td class="matrix-distance right ${row.distance==null?'unavailable':''}">${row.distance==null?'—':safe(distance)}</td><td class="matrix-fuel right ${row.fuel==null?'unavailable':''}">${row.fuel==null?'—':matrixMoney(row.fuel,'ARS')}</td><td class="matrix-total right ${row.total==null?'unavailable':''}">${row.total==null?'—':matrixMoney(row.total,'ARS')}</td></tr>`}
function matrixTable(rows){const sortedRows=matrixFilteredRows(rows);const sourceRows=matrixRowsWithIdentityVisibility(sortedRows);const identityCount=matrixIdentityCount(sourceRows);const summary=`${sourceRows.length} ${copy('matrixNativeRows')} · ${identityCount} ${copy('matrixNativeProducts')}`;return `<div class="matrix-summary"><strong>${summary}</strong><span>${copy('matrixEvidence')}</span></div><div class="matrix-scroll" id="matrixScroll" tabindex="0" aria-label="${safe(copy('matrixAria'))}"><table class="price-matrix"><thead><tr><th class="matrix-product"><button data-action="matrix-sort" data-sort="product">${copy('matrixProduct')} <span>↕</span></button></th><th class="matrix-pack right"><button data-action="matrix-sort" data-sort="pack">${copy('matrixPack')} <span>↕</span></button></th><th class="matrix-unit right"><button data-action="matrix-sort" data-sort="unit">${copy('matrixUnit')} <span>↓</span></button></th><th class="matrix-store"><button data-action="matrix-sort" data-sort="store">${copy('matrixStore')} <span>↕</span></button></th><th class="matrix-distance right"><button data-action="matrix-sort" data-sort="distance">${copy('matrixDistance')} <span>↕</span></button></th><th class="matrix-fuel right">${copy('matrixFuel')}</th><th class="matrix-total right">${copy('matrixTripTotal')}</th></tr></thead><tbody>${sourceRows.length?sourceRows.map((row,index)=>matrixRow(row,index)).join(''):`<tr><td class="matrix-empty" colspan="7">${copy('matrixNoMatches')}</td></tr>`}</tbody></table></div><div class="matrix-footnote"><span>${copy('matrixPinned')}</span><span class="matrix-sidehint">${copy('matrixMoreColumns')}</span></div>`}
function search(){const nativeRows=matrixRowsForNative(state.nativeSearchState);const stores=matrixStoreOptions(nativeRows);const storeOptions=stores.map(store=>`<option value="${safe(store.name)}" ${state.matrixStore===store.name?'selected':''}>${safe(store.name)}${store.distance!=null?` · ${safe(distanceLabel(store.distance))}`:''}</option>`).join('');return `<section class="content search-content"><div class="search-context"><span class="pill orange">ARS · Argentina</span><button type="button" class="preview-origin tap-link" data-action="choose-search-location" aria-label="${safe(copy('changeLocation'))}: ${safe(nativeAreaLabel())}" title="${safe(nativeAreaLabel())} · ${safe(copy('previewOriginNote'))}">${icons('pin')}<span>${safe(nativeAreaLabel())} · ${copy('changeLocation')}</span></button></div><form class="search-bar" id="searchForm">${icons('search')}<input id="searchQuery" name="query" autocomplete="off" aria-label="${safe(copy('searchInput'))}" placeholder="${safe(copy('nameBrandQuantity'))}" value="${safe(state.query)}"><button class="icon-button" type="button" id="clearQuery" aria-label="${safe(copy('clearSearch'))}">${icons('close')}</button><button class="btn btn-primary" type="submit" aria-label="${safe(copy('search'))}">${icons('arrow')}</button></form><div class="matrix-controlbar"><label>${copy('matrixStoreFilter')}<select id="matrixStore" aria-label="${safe(copy('matrixStoreFilter'))}"><option value="all" ${state.matrixStore==='all'?'selected':''}>${copy('matrixAllStores')}</option>${storeOptions}</select></label><label>${state.nativeSearchState?.hasMore||state.nativeSearchState?.previousPage!=null?copy('nativePageSort'):copy('matrixSortFilter')}<select id="matrixSort" aria-label="${safe(copy('matrixSortFilter'))}"><option value="unit" ${state.matrixSort==='unit'?'selected':''}>${copy('matrixSortUnit')}</option><option value="pack" ${state.matrixSort==='pack'?'selected':''}>${copy('matrixSortPack')}</option><option value="product" ${state.matrixSort==='product'?'selected':''}>${copy('matrixSortProduct')}</option><option value="store" ${state.matrixSort==='store'?'selected':''}>${copy('matrixSortStore')}</option><option value="distance" ${state.matrixSort==='distance'?'selected':''}>${copy('matrixSortDistance')}</option></select></label><span class="matrix-control-hint">${safe(matrixSortLabel())}</span></div><div class="chip-row search-categories"><button class="chip ${state.category==='Todos'?'active':''}" data-action="category" data-category="Todos">${copy('all')}</button><button class="chip ${state.category==='Leche'?'active':''}" data-action="category" data-category="Leche">${copy('milk')}</button><button class="chip ${state.category==='Arroz'?'active':''}" data-action="category" data-category="Arroz">${copy('rice')}</button><button class="chip ${state.category==='Aceite'?'active':''}" data-action="category" data-category="Aceite">${copy('oil')}</button></div><div id="resultsArea">${nativeResults(state.nativeSearchState)}</div></section>`}
function results(items){return nativeResults(items)}
function searchUnavailable(){return `<div class="empty-state search-empty">${icons('info')}<strong>${copy('nativeUnavailable')}</strong><p>${copy('nativeEvidence')}</p></div>`}
function nativeClarification(payload){const clarification=payload?.clarification;if(!clarification||!Array.isArray(clarification.choices)||clarification.choices.length<1)return '';const choices=clarification.choices.map(choice=>{const label=state.language===LANGUAGES.EN?(choice.labelEn||choice.label):choice.label;const choiceId=choice.id||choice.predicateId||'';return `<button class="clarification-choice" type="button" data-action="native-clarification" data-query="${safe(payload.query||state.query)}" data-choice-id="${safe(choiceId)}" aria-label="${safe(label)}"><span>${safe(label)}</span>${icons('arrow')}</button>`}).join('');const more=clarification.hasMore?`<button class="btn btn-soft btn-fill" data-action="native-clarification-more" ${state.nativeSearchPending?'disabled':''}>${state.nativeSearchPending?copy('nativeLoadingForms'):copy('nativeLoadMoreForms')} ${icons('arrow')}</button>`:'';return `<div class="card search-clarification" role="group" aria-labelledby="searchClarificationTitle"><div class="section-label" id="searchClarificationTitle">${copy('searchClarificationTitle')}</div><p class="small">${copy('searchClarificationBody')}</p><div class="clarification-choices">${choices}</div>${more?`<div class="stack" style="margin-top:10px">${more}</div>`:''}<div class="micro">${copy('searchClarificationObserved')}</div></div>`}
function nativeResults(payload){if(state.nativeSearchPending&&!payload)return `<div class="empty-state search-empty">${icons('search')}<strong>${copy('nativeLoading')}</strong><p>${copy('nativeEvidence')}</p></div>`;if(!payload)return `<div class="empty-state search-empty">${icons('search')}<strong>${copy('searchProduct')}</strong><p>${copy('nativeEvidence')}</p></div>`;const matches=payload.matches||[];if(payload.mode==='AUTHORIZATION_UNAVAILABLE'||payload.mode==='TEMPORARILY_UNAVAILABLE'||payload.mode==='TIMEOUT'||payload.mode==='LOADING'||payload.mode==='STALE_RELEASE')return `<div class="empty-state search-empty">${icons('info')}<strong>${copy('nativeUnavailable')}</strong><p>${safe(nativeStatus(payload))}</p></div>`;const clarification=nativeClarification(payload);if(!matches.length)return clarification||`<div class="empty-state search-empty">${icons('search')}<strong>${copy('nativeNoMatches')}</strong><p>${safe(nativeStatus(payload))}</p></div>`;const previous=payload.previousPage!=null?`<button class="btn btn-soft" data-action="native-previous-page" ${state.nativeSearchPending?'disabled':''}>${copy('nativePreviousPage')}</button>`:'';const next=payload.hasMore?`<button class="btn btn-soft" data-action="native-load-more" ${state.nativeSearchPending?'disabled':''}>${state.nativeSearchPending?copy('nativeLoadingMore'):copy('nativeLoadMore')} ${icons('arrow')}</button>`:'';const paging=previous||next?`<nav class="row" style="margin-top:14px;justify-content:space-between" aria-label="${copy('nativePage')}">${previous}<span class="micro" aria-live="polite">${copy('nativePage')} ${Number(payload.page||0)+1} · ${(payload.matches||[]).length} ${copy('nativeOf')} ${Number(payload.totalIdentityCount||(payload.matches||[]).length)}</span>${next}</nav>`:'';return clarification+matrixTable(matrixRowsForNative(payload))+paging}

function nativeProductCard(match,generation,index){return matrixRow({id:nativeProductId(generation,index),product:match.displayName||'',brand:match.brand||'',quantity:match.packageQuantityLabel||'',native:true,match,identityKey:match.identityKey||'',query:state.query,offerKey:''},index,true)}
function nativeOfferRows(match){const offers=Array.isArray(match?.offers)?match.offers:[];if(!offers.length)return `<div class="empty-state" style="padding:18px 8px">${icons('info')}<strong>${copy('nativeNoOffers')}</strong><p>${copy('nativeEvidence')}</p></div>`;return `<div class="stack">${offers.map(offer=>{const unit=offer?.unitPriceAmount!=null?nativeCurrency(offer.unitPriceAmount,offer.unitPriceCurrency||offer.currency||'ARS'):copy('nativePriceUnavailable');const pack=offer?.priceAmount!=null?nativeCurrency(offer.priceAmount,offer.currency||'ARS'):copy('nativePriceUnavailable');return `<div class="card"><div class="split"><strong>${safe(offer.storeName||copy('nativeIdentityOnly'))}</strong><span class="pill">${safe(nativeFreshnessLabel(offer.freshness))}</span></div><div class="split" style="margin-top:8px"><span class="small">${copy('nativeUnitPrice')}</span><strong>${safe(unit)}</strong></div><div class="split" style="margin-top:4px"><span class="micro">${copy('nativePackagePrice')}</span><span class="micro">${safe(pack)}</span></div></div>`}).join('')}</div>`}
function nativeDetail(){const detail=state.nativeDetailState;const match=detail?.match;if(!match)return `<section class="content"><div class="empty-state">${icons('search')}<strong>${copy('nativeStaleDetail')}</strong><button class="btn btn-primary" data-nav="search">${copy('searchProducts')}</button></div></section>`;const product=state.nativeProducts.get(detail.id)||{id:detail.id,native:true,brand:match.brand||'',name:match.displayName||'',quantity:match.packageQuantityLabel||'',match};const offers=Array.isArray(match.offers)?match.offers:[];const first=offers[0];const unit=first?.unitPriceAmount!=null?nativeCurrency(first.unitPriceAmount,first.unitPriceCurrency||first.currency||'ARS'):copy('nativePriceUnavailable');const packagePrice=first?.priceAmount!=null?nativeCurrency(first.priceAmount,first.currency||'ARS'):copy('nativePriceUnavailable');const saved=nativeSavedHas(match.identityKey);return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('backResults')}</button><div class="eyebrow">${copy('nativeDetailTitle')}</div><div class="detail-top"><span class="detail-brand">${safe(match.brand||'')} · ${safe(nativeAreaLabel())}</span><h1 class="detail-title">${safe(match.displayName||'')}</h1><div class="small">${safe(match.packageQuantityLabel||'')} · ${safe(match.sourceLabel||copy('nativeIdentityOnly'))}</div></div><div class="detail-image-placeholder"><span class="icon-circle">${icons('camera')}</span><strong style="font-size:14px">${copy('noCatalogPhotos')}</strong><p>${copy('photoCopy')}</p><button class="btn btn-primary" data-action="photos" data-id="${safe(product.id)}">${icons('camera')} ${copy('googleAction')} ${icons('arrow')}</button><div class="disclaimer">${copy('externalDisclaimer')}</div></div><div class="detail-metric"><div class="card"><div class="eyebrow" style="font-size:9px">${copy('pricePrefix')}${copy('priceLiter')}</div><strong>${safe(unit)}</strong><div class="micro">${offers.length?copy('nativeEvidence'):copy('nativeNoOffers')}</div></div><div class="card"><div class="eyebrow" style="font-size:9px">${copy('packageTotalUpper')}</div><strong>${safe(packagePrice)}</strong><div class="micro">${safe(match.packageQuantityLabel||'')}</div></div></div><div class="section-header"><strong>${copy('context')}</strong><span class="pill orange">${offers.length} ${copy('nativeOfferCount')}</span></div>${nativeOfferRows(match)}<div class="card stack" style="margin-top:12px"><div class="small">${copy('nativeDetailIntro')}</div><button class="btn btn-accent btn-fill" data-action="native-detail-save">${icons('bookmark')} ${saved?copy('nativeSavedAction'):copy('nativeSaveAction')}</button></div></section>`}
function nativeBasket(){if(state.nativeSavedPending)return `<section class="content"><div class="empty-state">${icons('basket')}<strong>${copy('nativeLoading')}</strong><p>${copy('nativeBasketIntro')}</p></div></section>`;const payload=state.nativeSavedState;const items=payload?.items||[];const basket=payload?.basket;if(!items.length)return `<section class="content"><div class="page-top"><div><div class="eyebrow">${copy('nativeBasketTitle')}</div><h1 class="page-title">${copy('basketTitle')}</h1><div class="small">${copy('nativeBasketIntro')}</div></div><span class="pill">0</span></div><div class="empty-state">${icons('basket')}<strong>${copy('nativeBasketEmpty')}</strong><p>${copy('nativeEvidence')}</p><button class="btn btn-primary" data-nav="search">${copy('searchProducts')} ${icons('arrow')}</button></div></section>`;const lines=basket?.lines||items.map(item=>({identityKey:item.identityKey,productName:item.displayName,packageQuantityText:item.packageQuantityLabel||'',lineTotalText:null,storeName:null,availabilityText:copy('nativeBasketUnknown'),missing:true}));const plan=basket?.plan;const planLoading=Boolean(basket?.planLoading);const canPlan=Boolean(basket?.canPlan);return `<section class="content"><div class="page-top"><div><div class="eyebrow">${copy('nativeBasketTitle')}</div><h1 class="page-title">${copy('basketTitle')}</h1><div class="small">${copy('nativeBasketIntro')}</div></div><span class="pill">${itemCount(items.length)}</span></div><div class="stack" style="margin-top:12px">${lines.map(line=>`<div class="card basket-entry"><div class="item-label"><strong>${safe(line.productName||'')}</strong><small>${safe(line.packageQuantityText||'')} · ${safe(line.missing?copy('nativeBasketUnknown'):(line.lineTotalText||''))}</small>${line.storeName?`<small>${safe(line.storeName)}</small>`:''}</div><button class="bookmark-button is-saved" data-action="native-remove-saved" data-identity-key="${safe(line.identityKey)}" aria-label="${safe(copy('nativeBasketRemove'))}">${icons('bookmark')}</button></div>`).join('')}</div>${plan?.totalText?`<div class="summary-total" style="margin-top:12px"><div class="split"><span style="font-size:12px">${copy('nativeBasketPlan')}</span><span class="pill" style="background:#ffffff22;color:inherit">ARS</span></div><div class="number-lg" style="margin-top:10px">${safe(plan.totalText)}</div><div class="micro" style="color:#dadbd5">${safe(plan.coverageText||'')}</div></div>`:''}<div class="card stack" style="margin-top:12px"><strong>${copy('nativeBasketTitle')}</strong><p class="micro">${safe(basket?.evidenceNotice||copy('nativeEvidence'))}</p>${basket?.errorNotice?`<div class="preview-notice">${icons('info')} ${safe(basket.errorNotice)}</div>`:''}${planLoading?`<div class="preview-notice">${icons('info')} ${copy('nativeBasketPlanLoading')}</div>`:canPlan?`<button class="btn btn-accent btn-fill" data-action="native-plan">${icons('route')} ${copy('nativeBasketPlanAction')}</button>`:''}<button class="btn btn-primary btn-fill" data-nav="trip">${icons('route')} ${copy('estimateTravel')}</button><button class="btn btn-soft btn-fill" data-nav="search">${copy('keepSearching')} ${icons('arrow')}</button><button class="tap-link" data-action="native-refresh-saved">${copy('nativeBasketRefresh')}</button></div></section>`}
function nativeDataMode(){return true}
function basket(){return nativeBasket()}
function nativeSavedResults(payload){if(state.nativeSavedPending)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('nativeLoading')}</strong><p>${copy('nativeSavedIntro')}</p></div>`;if(!payload||payload.mode==='UNAVAILABLE')return `<div class="empty-state">${icons('info')}<strong>${copy('nativeSavedTitle')}</strong><p>${copy('nativeSavedIntro')}</p></div>`;const items=payload.items||[];return items.length?`<div class="section-header" style="margin:15px 0 10px"><strong>${items.length} ${copy('saved')}</strong><span class="micro">${copy('nativeSavedIdentityNote')}</span></div><div class="stack">${items.map(item=>`<div class="card saved-card"><div><strong style="font-size:13px">${safe(item.brand?item.brand+' · ':'')}${safe(item.displayName||'')}</strong><div class="micro">${safe(item.packageQuantityLabel||'')} · ${copy('nativeSavedIdentityNote')}</div><div class="micro">${safe(item.sourceLabel||'')}</div><div class="row" style="margin-top:8px"><button class="tap-link" data-action="native-good-price" data-identity-key="${safe(item.identityKey)}" data-display-name="${safe(item.displayName||'')}">${icons('check')} ${copy('goodPriceTool')}</button><button class="tap-link" data-action="native-saved-photos" data-brand="${safe(item.brand||'')}" data-display-name="${safe(item.displayName||'')}" data-quantity="${safe(item.packageQuantityLabel||'')}">${icons('camera')} ${copy('nativeOpenPhotos')}</button></div></div><button class="bookmark-button is-saved" data-action="native-remove-saved" data-identity-key="${safe(item.identityKey)}" aria-label="${safe(copy('nativeRemoveAction'))}">${icons('bookmark')}</button></div>`).join('')}</div>`:`<div class="empty-state">${icons('bookmark')}<strong>${copy('nativeSavedEmpty')}</strong><p>${copy('nativeSavedIdentityNote')}</p><button class="btn btn-primary" data-nav="search">${copy('searchProducts')} ${icons('arrow')}</button></div>`}
function observedSelectionStatus(status){switch(String(status||'')){case'READY_FOR_PREFILL_CHECK':return copy('observedPriceSelectionReady');case'DISPLAY_METADATA_INCOMPLETE':return copy('observedPriceBlocked');default:return copy('observedPriceSelectionNeeded')}}
function observedPrefillMessage(value){const raw=String(value||'');if(state.language===LANGUAGES.EN)return raw;const map={'The selected saved product and store can prefill identity details for a later observed-price confirmation.':copy('observedPriceSelectionReady'),'Choose one saved product and one saved store again before checking.':copy('observedPriceSelectionNeeded'),'That saved product is no longer available. Choose a saved product again.':copy('observedPriceBlocked'),'That saved store is no longer available. Choose a saved store again.':copy('observedPriceBlocked'),'This saved product cannot be safely identified for observed-price confirmation yet.':copy('observedPriceBlocked'),'This saved product identifier cannot be verified for observed-price confirmation. Choose another saved product.':copy('observedPriceBlocked'),'The selected saved product needs a current display name before it can be checked.':copy('observedPriceBlocked'),'The selected saved store needs a current display name before it can be checked.':copy('observedPriceBlocked')};return map[raw]||copy('observedPriceBlocked')}
function observedSelectionRow(row,side){const action=row?.action||{};const kind=String(action.kind||'');const key=action.key?` data-key="${safe(action.key)}"`:'';const selected=Boolean(row?.selected);const label=kind==='CLEAR_PRODUCT'?copy('observedPriceClearProduct'):kind==='CLEAR_STORE'?copy('observedPriceClearStore'):side==='product'?copy('observedPriceChooseProduct'):copy('observedPriceChooseStore');return `<div class="card saved-card"><div class="stack" style="gap:3px"><strong style="font-size:13px">${safe(row?.title||'')}</strong><span class="micro">${selected?copy('observedPriceSelectionReady'):side==='product'?copy('observedPriceChooseProduct'):copy('observedPriceChooseStore')}</span></div><button class="btn ${selected?'btn-soft':'btn-outline'}" data-action="observed-select" data-kind="${safe(kind)}"${key}>${selected?icons('check'):icons('plus')} ${label}</button></div>`}
function nativeObservedSelection(payload){if(state.nativeObservedPricePending&&!payload?.selection)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('observedPriceLoading')}</strong><p>${copy('observedPriceEvidenceNote')}</p></div>`;const selection=payload?.selection;if(!selection)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('observedPriceNoSaved')}</strong><p>${copy('observedPriceEvidenceNote')}</p><button class="btn btn-primary" data-nav="saved">${copy('observedConfirmCancel')}</button></div>`;const products=Array.isArray(selection.products)?selection.products:[];const stores=Array.isArray(selection.stores)?selection.stores:[];const hasRows=products.length||stores.length;const prefill=payload?.prefill;const notice=selection.status==='DISPLAY_METADATA_INCOMPLETE'?copy('observedPriceBlocked'):selection.status==='READY_FOR_PREFILL_CHECK'?copy('observedPriceSelectionReady'):copy('observedPriceSelectionNeeded');return `<div class="card stack"><div class="split"><span class="section-label" style="margin:0">${copy('observedPriceSelectionCard')}</span><span class="pill orange">${safe(observedSelectionStatus(selection.status))}</span></div><div class="preview-notice">${icons('info')} ${copy('observedPriceEvidenceNote')}</div></div>${!hasRows?`<div class="empty-state">${icons('bookmark')}<strong>${copy('observedPriceNoSaved')}</strong><p>${copy('observedPriceEvidenceNote')}</p></div>`:`<div class="section-header"><strong>${safe(selection.productSectionTitle||copy('observedPriceChooseProduct'))}</strong></div><div class="stack">${products.map(row=>observedSelectionRow(row,'product')).join('')}</div><div class="section-header"><strong>${safe(selection.storeSectionTitle||copy('observedPriceChooseStore'))}</strong></div><div class="stack">${stores.map(row=>observedSelectionRow(row,'store')).join('')}</div><div class="card stack" style="margin-top:12px"><strong>${safe(notice)}</strong>${selection.notice?`<p class="micro">${copy('observedPriceBlocked')}</p>`:''}<div class="row" style="flex-wrap:wrap">${selection.clearSelectionAction?`<button class="tap-link" data-action="observed-select" data-kind="CLEAR_SELECTION">${icons('back')} ${copy('observedPriceClearProduct')} · ${copy('observedPriceClearStore')}</button>`:''}</div>${selection.checkAvailable?`<button class="btn btn-accent btn-fill" data-action="observed-check">${icons('arrow')} ${copy('observedPriceCheckPair')}</button>`:`<div class="preview-notice">${icons('info')} ${copy('observedPriceSelectionNeeded')}</div>`}</div>`}${prefill?`<div class="card stack" style="margin-top:12px"><div class="eyebrow">${safe(prefill.status==='IDENTITY_PREFILL_READY'?copy('observedPriceSelectionReady'):copy('observedPriceBlocked'))}</div><strong>${safe(observedPrefillMessage(prefill.message))}</strong>${prefill.productName?`<div class="small">${copy('observedConfirmIdentity')}: ${safe(prefill.productName)} · ${safe(prefill.storeDisplayName||'')}</div>`:''}</div>`:''}`}
function observedDraftStatus(draft){if(!draft)return copy('observedConfirmMissing');return draft.status==='NON_BYTE_INPUT_COMPLETE'?copy('observedConfirmReady'):copy('observedConfirmMissing')}
function observedProofSummary(proof){switch(String(proof?.status||'')){case'READY':return `${copy('observedConfirmProofReady')}${proof.byteLength?` · ${safe(proof.byteLength)} bytes`:''}`;case'REJECTED':return copy('observedConfirmProofRejected');case'AWAITING_SELECTION':return copy('observedConfirmProofWaiting');default:return copy('observedConfirmProofWaiting')}}
function observedActionStatus(value){switch(String(value||'')){case'CONFIRMED':return copy('observedConfirmSuccess');case'SUBMITTING':return copy('observedConfirmSubmitting');case'ERROR':return copy('observedConfirmError');case'READY':return copy('observedConfirmReady');default:return copy('observedConfirmMissing')}}
function nativeObservedConfirmation(payload){if(state.nativeObservedPricePending&&!payload?.confirmation)return `<div class="empty-state">${icons('check')}<strong>${copy('observedPriceLoading')}</strong><p>${copy('observedConfirmIntro')}</p></div>`;const confirmation=payload?.confirmation;if(!confirmation)return `<div class="empty-state">${icons('info')}<strong>${copy('observedPriceNoSaved')}</strong><button class="btn btn-primary" data-action="observed-cancel">${copy('observedConfirmCancel')}</button></div>`;const form=state.observedPriceForm;const draft=confirmation.draft;const proof=confirmation.proof||{};const action=confirmation.action||{};const submitEnabled=Boolean(action.actionEnabled);const statusMessage=action.status==='CONFIRMED'?copy('observedConfirmSuccess'):action.status==='SUBMITTING'?copy('observedConfirmSubmitting'):action.message?observedNativeMessage(action.message):copy('observedConfirmReady');const missing=Array.isArray(draft?.missing)?draft.missing:[];return `<div class="card stack"><div class="eyebrow">${copy('observedConfirmTitle')}</div><h1 class="page-title" style="margin:0">${copy('observedConfirmTitle')}</h1><p class="small" style="margin:0">${copy('observedConfirmIntro')}</p><div class="muted-panel"><div class="section-label" style="margin:0 0 5px">${copy('observedConfirmIdentity')}</div><strong>${safe(confirmation.productName||'')}</strong><div class="micro">${safe(confirmation.storeDisplayName||'')}</div></div></div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmAmount')}</strong><span class="pill">ARS</span></div><div class="inline-form"><label class="small" style="flex:1">${copy('observedConfirmAmount')}<input id="observedAmount" class="inline-form-input" inputmode="decimal" value="${safe(form.amount)}" placeholder="${safe(copy('observedConfirmDecimalHint'))}"></label><label class="small" style="width:92px">${copy('observedConfirmCurrency')}<input id="observedCurrency" class="inline-form-input" value="${safe(form.currency)}" maxlength="12"></label></div>${confirmation.priceInputError?`<div class="preview-notice">${icons('info')} ${copy('observedConfirmInputError')}</div>`:''}<button class="btn btn-soft btn-fill" data-action="observed-set-price">${copy('observedConfirmSetPrice')}</button></div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmDate')}</strong><span class="pill">${copy('observedConfirmTime')}</span></div><div class="inline-form"><label class="small" style="flex:1">${copy('observedConfirmDate')}<input id="observedDate" class="inline-form-input" inputmode="numeric" value="${safe(form.date)}" placeholder="${safe(copy('observedConfirmDateHint'))}"></label><label class="small" style="flex:1">${copy('observedConfirmTime')}<input id="observedTime" class="inline-form-input" inputmode="numeric" value="${safe(form.time)}" placeholder="${safe(copy('observedConfirmTimeHint'))}"></label><label class="small" style="width:78px">UTC<input id="observedOffset" class="inline-form-input" value="${safe(form.utcOffset)}" placeholder="${safe(copy('observedConfirmOffsetHint'))}"></label></div>${confirmation.observedAtInputError?`<div class="preview-notice">${icons('info')} ${copy('observedConfirmInputError')}</div>`:''}<button class="btn btn-soft btn-fill" data-action="observed-set-time">${copy('observedConfirmSetTime')}</button></div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmProofReference')}</strong><span class="pill">${safe(observedProofSummary(proof))}</span></div><label class="small">${copy('observedConfirmProofReference')}<input id="observedArtifact" class="inline-form-input" value="${safe(form.artifactId)}" placeholder="${safe(copy('observedConfirmProofWaiting'))}"></label><div class="small">${copy('observedConfirmProofType')}</div><div class="row" style="flex-wrap:wrap"><button class="chip ${form.proofType==='RECEIPT'?'active':''}" data-action="observed-proof-type" data-proof-type="RECEIPT">${copy('observedConfirmReceipt')}</button><button class="chip ${form.proofType==='PRICE_TAG'?'active':''}" data-action="observed-proof-type" data-proof-type="PRICE_TAG">${copy('observedConfirmPriceTag')}</button></div><div class="row" style="flex-wrap:wrap"><button class="btn btn-outline" data-action="observed-proof-picker">${icons('camera')} ${copy('observedConfirmChooseFile')}</button><button class="btn btn-soft" data-action="observed-set-proof">${copy('observedConfirmSetProof')}</button></div>${confirmation.proofReferenceInputError?`<div class="preview-notice">${icons('info')} ${copy('observedConfirmInputError')}</div>`:''}</div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmFinal')}</strong><span class="pill ${action.status==='CONFIRMED'?'green':''}">${safe(observedActionStatus(action.status))}</span></div><strong>${safe(observedDraftStatus(draft))}</strong>${missing.length?`<div class="stack">${missing.map(item=>`<div class="micro">• ${safe(item.label||'')}</div>`).join('')}</div>`:''}<p class="micro">${safe(statusMessage)}</p><div class="preview-notice">${icons('info')} ${copy('observedConfirmNotice')}</div><button class="btn btn-accent btn-fill" data-action="observed-submit" ${submitEnabled?'':'disabled'}>${icons('check')} ${copy('observedConfirmSubmit')}</button><button class="tap-link" data-action="observed-cancel">${icons('back')} ${copy('observedConfirmCancel')}</button></div>`}
function observedPrice(){return `<section class="content"><button class="detail-back" data-action="observed-cancel">${icons('back')} ${copy('observedConfirmCancel')}</button><div class="eyebrow">${copy('observedPriceLabel')}</div><h1 class="page-title">${copy('observedPriceTitle')}</h1><p class="hero-copy">${copy('observedPriceIntro')}</p><div class="stack" style="margin-top:12px">${nativeObservedSelection(state.nativeObservedPriceSelection?{selection:state.nativeObservedPriceSelection,prefill:state.nativeObservedPricePrefill}:null)}</div></section>`}
